import {nextGoal,latestImpact} from './guild-goals.mjs?v=1';
import {GUILDS,PLAYERS,player,guild,loadTrial,saveTrial,freshTrial,standings,guildStandings,qualifierSquad,lockReason,lockSquads,closeReason,closeTrial,fillExamples,abandonActive,entryReason,usedAttempts,trialUrl,formatTime,LIMIT,compareRuns} from './guild-trial.mjs?v=1';
function localStorageSafe(){try{return globalThis.localStorage;}catch{return null;}}
export function mountGuildHall({doc=globalThis.document,storage=localStorageSafe(),events=globalThis.window}={}){
 const $=id=>doc.getElementById(id);let loaded=loadTrial(storage),state=loaded.state,blocked=!!loaded.error,view='players';
 function notify(message){$('hall-notice').hidden=!message;$('hall-notice').textContent=message||'';}
 if(!blocked&&!saveTrial(storage,state)){blocked=true;notify('Browser saving is unavailable. Rehearsal runs cannot be recorded here; solo play is still available.');}else if(loaded.error)notify(loaded.error);
 $('player-seat').innerHTML=GUILDS.map(g=>`<optgroup label="${g.name}">${PLAYERS.filter(p=>p.guild===g.id).map(p=>`<option value="${p.id}">${p.name} · ${g.name}</option>`).join('')}</optgroup>`).join('');
 function commit(change,message){try{const fresh=loadTrial(storage);if(fresh.error)throw Error(fresh.error);const next=change(fresh.state);if(!saveTrial(storage,next))throw Error('Could not save the rehearsal. No change was recorded.');state=next;blocked=false;notify(message);render();return true;}catch(e){notify(e.message);return false;}}
 function render(){
 const current=player(state.seat),stage=state.phase==='qualifiers'?'qualifiers':'finals',finished=state.phase==='complete',round=stage==='qualifiers'?'Qualifier':'Squad final',board=guildStandings(state);
 $('player-seat').value=state.seat;
 const ownGuild=guild(current.guild),ownRows=standings(state,stage,stage==='qualifiers'?current.guild:null),ownRow=ownRows.find(p=>p.id===current.id),ownBest=ownRow.best,goal=nextGoal(state),team=board.find(g=>g.id===current.guild),rival=board.find(g=>g.id!==current.guild);
 $('guild-name').textContent=ownGuild.name;$('your-crest').textContent=ownGuild.mark;$('your-crest').classList.toggle('teal',ownGuild.color==='teal');$('guild-identity-copy').textContent='Playing as '+current.name+' · Local rehearsal seat';
 $('your-best').textContent=ownBest?ownBest.value+' / 6':'No escape';$('your-rank').textContent=ownRow.rank?'#'+ownRow.rank:'Unranked';$('your-rank-label').textContent=stage==='qualifiers'?'Guild position':'Player position';$('your-attempts').textContent=finished?'Closed':Math.max(0,LIMIT-usedAttempts(state,state.seat,stage))+' / '+LIMIT;
 $('goal-title').textContent=goal.title;$('goal-copy').textContent=goal.copy;
 const qualifierRows=standings(state,'qualifiers',current.guild).filter(p=>p.best),boundaryTied=stage==='qualifiers'&&qualifierRows[2]&&qualifierRows[3]&&compareRuns(qualifierRows[2].best,qualifierRows[3].best)===0;
 const ownRoster=stage==='qualifiers'?qualifierSquad(state,current.guild):state.rosters[current.guild];
 $('squad-label').textContent=stage==='qualifiers'?'THREE PLACES TO EARN':'YOUR LOCKED SQUAD';$('squad-title').textContent=stage==='qualifiers'?'Who’s coming with you?':'Three players. Your guild.';$('squad-summary').textContent=stage==='qualifiers'?ownRoster.length+' / 3 positions filled':team.banked+' / 3 escapes banked';
 $('squad-slots').innerHTML=Array.from({length:3},(_,i)=>{const id=ownRoster[i],p=player(id),r=p?standings(state,stage).find(r=>r.id===id):null;return `<article class="squad-slot ${id===current.id?'is-you':''} ${!p?'empty':''}"><span class="slot-number">0${i+1}</span><strong>${p?p.name:'Open place'}${id===current.id?' <small>YOU</small>':''}</strong><span class="slot-detail">${p?(r.best?r.best.value+' / 6 · '+formatTime(r.best.ticks):'Waiting for an escape'):'Bank a qualifier'}</span><small>${p?(boundaryTied&&compareRuns(r.best,qualifierRows[2].best)===0?'Tied place · needs another run':r.best?.example?'Example score':r.best?'Played here':'Squad member'):'Your name could be here'}</small></article>`;}).join('');
 $('squad-note').textContent=boundaryTied?'The third-place cutoff is tied. Another qualifier must settle it before squads lock.':stage==='qualifiers'?'Positions can change until squads lock. The top three successful qualifiers go through.':'Qualifier scores reset for the final. Your squad’s best three escapes now count together.';
 $('rivalry-title').textContent=finished?(team.rank===1?(rival.rank===1?'A trophy shared.':'You brought it home.'):'A rivalry to run back.'):'Your guild. Their challenge.';
 $('rivalry-score').innerHTML=[team,rival].map((g,i)=>{const qualified=qualifierSquad(state,g.id),examples=stage==='qualifiers'?standings(state,'qualifiers',g.id).some(p=>p.best?.example):g.examples;return `<div class="rival-side ${i===0?'home-side':''}"><span class="eyebrow">${i===0?'YOUR GUILD':'RIVAL GUILD'}</span><strong>${g.name}</strong><span class="rival-number">${stage==='qualifiers'?qualified.length+' / 3':g.value+' / 18'}</span><small>${stage==='qualifiers'?'Provisional squad places':g.banked+' / 3 escapes · '+(g.banked?formatTime(g.ticks):'no time yet')}</small>${examples?'<small class="example-tag">Includes example scores</small>':''}</div>`;}).join('');
 $('rivalry-copy').textContent=stage==='qualifiers'?'Earn your place first. Guild scores start fresh when both squads lock.':!team.qualified||!rival.qualified?'The result stays provisional until both squads have three successful escapes.':team.value!==rival.value?(team.value>rival.value?'Your guild is ahead by ':'Your guild trails by ')+Math.abs(team.value-rival.value)+' treasure points.':team.ticks!==rival.ticks?'Treasure is tied. Your guild is '+formatTime(Math.abs(team.ticks-rival.ticks))+(team.ticks<rival.ticks?' faster on combined time.':' behind on combined time.'):'Equal treasure and exact time. Both guilds share first place.';
 for(const [i,key] of ['qualifiers','finals','complete'].entries()){const n=['qualifiers','finals','complete'].indexOf(state.phase);$('stage-'+key).classList.toggle('current',i===n);$('stage-'+key).classList.toggle('done',i<n);$('stage-'+key).setAttribute('aria-current',i===n?'step':'false');}
 $('round-label').textContent=finished?'REHEARSAL COMPLETE':stage==='qualifiers'?'GUILD QUALIFIERS':'SQUADS LOCKED · THE FINAL';
 $('entry-title').textContent=finished?'The job is done.':'One More Thing.';
 $('entry-copy').textContent=finished?'See what your squad brought home.':stage==='qualifiers'?'Bank treasure. Earn your squad place.':'Your next escape counts for your guild.';
 const why=blocked?'Saving is unavailable. Reset or enable browser storage.':entryReason(state,state.seat,stage);
 $('enter-run').textContent=finished?'Rehearsal complete':stage==='qualifiers'?'Play qualifier →':'Play squad final →';
 if(!blocked&&(finished||(stage==='finals'&&!state.rosters[current.guild].includes(current.id)))){$('enter-run').textContent=finished?'See the results ↓':'Follow your squad ↓';$('enter-run').setAttribute('aria-disabled','false');$('enter-run').setAttribute('href','#standings');$('enter-run').onclick=null;}else if(why){$('enter-run').setAttribute('aria-disabled','true');$('enter-run').setAttribute('href','#entry-title');$('enter-run').onclick=e=>{e.preventDefault();notify(why);};}else{$('enter-run').setAttribute('aria-disabled','false');$('enter-run').setAttribute('href',trialUrl(state));$('enter-run').onclick=null;}
 $('entry-status').textContent=finished?'Final scores are locked. The trophy is a local rehearsal result.':why||'An attempt begins when you press Play inside the game.';
 const impact=latestImpact(state);$('recent-result').hidden=!impact;
 if(impact){$('recent-title').textContent=impact.title;$('recent-copy').textContent=impact.copy;}
 $('guild-cards').innerHTML=GUILDS.map(g=>{const roster=stage==='qualifiers'?qualifierSquad(state,g.id):state.rosters[g.id],members=standings(state,stage,g.id),team=board.find(b=>b.id===g.id),winner=finished&&team.rank===1;
 return `<article class="guild-card ${g.color==='teal'?'teal':''} ${current.guild===g.id?'selected':''}"><div class="guild-cover"><span class="guild-tag">EXAMPLE GUILD / ${current.guild===g.id?'YOUR SELECTED SEAT':'OPPOSITION'}</span><span class="guild-crest" aria-hidden="true">${g.mark}</span></div><div class="guild-body"><h3>${g.name}</h3><p class="guild-motto">${g.motto}</p><p class="guild-meta">4 rehearsal seats · Founding Chog not linked · Local roster</p><div class="roster-label"><span>${stage==='qualifiers'?'QUALIFIER POSITIONS':'LOCKED SQUAD'}</span><span>${roster.length} / 3 PLACES</span></div><ul class="member-list">${members.map(p=>`<li><span><strong>${p.id===current.id?'You as ':''}${p.name} ${roster.includes(p.id)?'<span class="squad-number">◆</span>':''}</strong><small>${stage==='qualifiers'?(roster.includes(p.id)?'Currently in squad position':p.best?'Outside the top three':'Awaiting an escape'):(roster.includes(p.id)?'Squad member':'Reserve · not scoring')}</small></span><span class="member-score">${p.best?`${p.best.value} / 6 · ${formatTime(p.best.ticks)}<small>${p.best.example?'Example result':'Played here · unverified'}</small>`:'—'}</span></li>`).join('')}</ul><div class="trophy-slot ${winner?'winner':''}"><b aria-hidden="true">${winner?'✦':'◇'}</b><span>${winner?(board.filter(b=>b.rank===1).length>1?'Shared rehearsal trophy':'Burrows rehearsal trophy'):'A place for your first trophy'}<small>${winner?(team.examples?'Includes example scores · no prize':'Local results · no prize'):'Earned when this rehearsal closes'}</small></span></div></div></article>`;}).join('');
 $('standings-title').textContent=finished?'The rehearsal results':stage==='qualifiers'?'Qualifier standings':'Squad final standings';
 $('view-players').classList.toggle('active',view==='players');$('view-guilds').classList.toggle('active',view==='guilds');$('view-players').setAttribute('aria-pressed',String(view==='players'));$('view-guilds').setAttribute('aria-pressed',String(view==='guilds'));
 if(view==='players'){
  $('board-explanation').textContent='Best successful run per player. Higher treasure value wins; equal values use exact game time. Example scores are labelled.';
  const rows=standings(state,stage).filter(p=>stage==='qualifiers'||state.rosters[p.guild].includes(p.id));
  $('standings-content').innerHTML=`<table class="score-table"><caption class="sr-only">${round} player standings, local and unverified</caption><thead><tr><th scope="col">#</th><th scope="col">PLAYER / GUILD</th><th scope="col">HAUL</th><th scope="col">TIME</th></tr></thead><tbody>${rows.map(p=>`<tr class="${p.id===state.seat?'mine':''}"><td>${p.rank||'—'}</td><td><strong>${p.name}${p.id===state.seat?' · you':''}</strong><small>${guild(p.guild).name}</small>${p.best?`<small class="provenance">${p.best.example?'EXAMPLE SCORE':'PLAYED HERE · UNVERIFIED'}</small>`:''}</td><td>${p.best?p.best.value+' / 6':'—'}</td><td>${p.best?formatTime(p.best.ticks):'No escape'}</td></tr>`).join('')}</tbody></table>`;
 }else{
  $('board-explanation').textContent=stage==='qualifiers'?'Guild scores start fresh after squads lock. Qualifiers decide the three places in each squad.':'All three squad members must bank a run. Their treasure values are added, followed by combined time. Exact ties share placement.';
  $('standings-content').innerHTML=board.map(g=>`<article class="guild-score-row"><span>${g.rank||'—'}</span><div><h3>${g.name}</h3><p>${stage==='qualifiers'?'Awaiting the squad final':g.qualified?'All three players banked a run':g.banked+' / 3 escapes · provisional'}</p>${g.examples?'<small>Includes example scores</small>':''}${g.qualified?`<p>${g.members.map(m=>m.player.name+' '+m.best.value).join(' + ')} = ${g.value} treasure</p>`:''}</div><div class="guild-total">${g.value} / 18<small>${g.banked?formatTime(g.ticks):'No final times'}</small></div></article>`).join('');
 }
 const reason=blocked?'Saving is unavailable.':finished?'Results are closed. Reset to rehearse again.':stage==='qualifiers'?lockReason(state):closeReason(state);
 $('advance-round').textContent=finished?'Rehearsal complete':stage==='qualifiers'?'Lock squads & start final →':'Close rehearsal & award trophy →';$('advance-round').disabled=!!reason;$('advance-reason').textContent=reason||(stage==='qualifiers'?'Both squads are ready. Locking ends qualifiers and starts fresh final scores.':'Both squads have three escapes. Close now, or keep improving your runs.');
 $('round-next').hidden=!!reason;$('round-next').textContent=stage==='qualifiers'?'Both squads are ready · open round controls →':'All six escapes are in · open results controls →';
 $('host-summary').textContent=finished?'Results closed':!reason?(stage==='qualifiers'?'Squads ready to lock':'Ready to award trophy'):'Test the whole flow';
 $('fill-examples').disabled=blocked||finished;$('abandon-run').hidden=!state.attempts.some(a=>a.status==='active');
 }
 $('rehearsal-details').onclick=$('round-next').onclick=()=>{$('rehearsal-tools').open=true;};
 $('player-seat').onchange=e=>commit(s=>({...s,seat:player(e.target.value)?.id||s.seat}),'Rehearsal seat changed.');
 $('view-players').onclick=()=>{view='players';render();};$('view-guilds').onclick=()=>{view='guilds';render();};
 $('fill-examples').onclick=()=>commit(s=>fillExamples(s),'Empty seats now contain labelled example scores. Play your selected seat to contribute your own run.');
 $('abandon-run').onclick=()=>commit(abandonActive,'Unfinished attempt abandoned. It still counts towards the attempt limit.');
 $('advance-round').onclick=()=>commit(s=>s.phase==='qualifiers'?lockSquads(s):closeTrial(s),state.phase==='qualifiers'?'Squads locked. Final scores start from zero.':'Rehearsal complete. Results and the local trophy are ready.');
 $('reset-trial').onclick=()=>$('reset-dialog').showModal();
 $('confirm-reset').onclick=()=>{const next=freshTrial();if(!saveTrial(storage,next)){notify('Could not reset: browser saving is unavailable.');return;}state=next;blocked=false;$('reset-dialog').close();notify('Fresh rehearsal ready. Solo saves were not changed.');render();};
 function refresh(){const r=loadTrial(storage);if(r.error){blocked=true;notify(r.error);}else{state=r.state;blocked=false;}render();}
 events?.addEventListener?.('storage',refresh);render();
 return {get state(){return state;},render,destroy(){events?.removeEventListener?.('storage',refresh);}};
}
if(typeof document!=='undefined')mountGuildHall();
